function uhLife(f,id,n,r,x,y,p,d){let h=7;for(const ch of id+n)h=(h*31+ch.charCodeAt(0))>>>0;
 const has=w=>n.includes(w);const fm=m=>String(Math.floor(m/60)).padStart(2,'0')+'.'+String(m%60).padStart(2,'0');
 const staff=/นัก|พยาบาล|แพทย์|เจ้าหน้าที่|อาสา|ทนาย|อาจารย์|ผู้ประสานงาน|รองผู้อำนวยการ|พนักงาน|เภสัชกร/.test(n)&&!/ผู้อำนวยการโรงพยาบาลเครือข่าย/.test(n);
 let acts=null,sh=null,lunch=0,say=[];const row=UH_ROLE.find(e=>has(e[0]));
 if(staff&&row){acts=row[1];sh=row[2]||null;lunch=sh?1+(h%2):0;
  say=[sh?('เข้างาน '+fm(sh[0])+' น. เลิก '+fm(sh[1])+' น. พักเที่ยง '+(lunch===1?'11.30–12.30':'12.30–13.30')+' น. สลับกับเพื่อนให้มีคนประจำจุดตลอด'):'ที่นี่เปิดตลอด 24 ชั่วโมง เข้าเวรผลัดละ 8 ชั่วโมง']}
 else if(row){acts=row[1];sh=row[2]||null;if(sh)say=['นัดไว้ '+fm(sh[0])+' น.']}
 else{const kid=/เด็ก/.test(n);acts=kid?['เล่น','วาดรูป']:/รอ|โถง|พัก/.test(r)?['รอเรียกคิว','อ่านแผ่นพับ','คุยกับญาติ']:/ประชุม/.test(r)?['ฟังแผนดูแล','ถามข้อสงสัย']:/กลุ่ม/.test(r)?['เล่าประสบการณ์','ฟังเพื่อน']:['รับบริการ','ฟังคำอธิบาย','ถามข้อสงสัย'];
  const s0=510+(h%6)*30,du=150+(h%4)*45;sh=[s0,s0+du];say=['มาตามนัด '+fm(s0)+' น.']}
 const mv=UH_MOVE[f]&&UH_MOVE[f][id];
 const route=mv?mv:acts.flatMap((a,i)=>[[x,y,6000+((h>>(i*3))%5)*1500,p,d,a],[x,y,3000+((h>>(i*2))%4)*1000,p,d,'']]);
 const duty=sh?(m=>m>=sh[0]&&m<sh[1]&&!(lunch===1&&m>=690&&m<750)&&!(lunch===2&&m>=750&&m<810)):undefined;
 return {route,duty,say}}
