function loadCMH(at,f){f=f||1;loadPlace(f===1?'cmh':'cmh:'+f,{mk:'cmh',hosp:1,floor:0,place:'โรงพยาบาลอนามัยชุมชน  ฝึกงาน',bk:'cmh',bd:f,at,dir:f===1?'up':'down'});st.floor=0;st.cmhF=f}
function cmhOldBots(B,L,pre,L0,fid){fid=fid||0;const occ=new Set();if(L0){L0.forEach(x=>{const r=x.route&&x.route[0];if(r)occ.add(r[0]+','+r[1])});Object.values(CSLOT).forEach(v=>{if(v[0]===fid)occ.add(v[1]+','+v[2])})}(L||[]).forEach(b=>{const r0=b.route&&b.route[0];if(r0&&occ.has(r0[0]+','+r0[1]))return;const o=JSON.parse(JSON.stringify(b));o.id=pre+o.id;const mk=o.mask;delete o.mask;if(mk)o.duty=m=>mk[Math.floor(((m%1440)+1440)%1440/30)]==='1';B(o)})}
