function prList(c){const D=S.csDone||{};const N=PR_IDS.length,n=prDoneN();const L=PR_IDS.map(id=>CASES.find(x=>x.id===id)).filter(Boolean);
 const gc={};L.forEach(x=>{if(D[x.id])gc[D[x.id].g]=(gc[D[x.id].g]||0)+1});
 return `<div class="his-perk">เก็บเคสฝึกงานแล้ว <b>${n}/${N}</b> เคส${n>=N?'  ครบแล้ว ผ่านการฝึกงาน':''}${Object.keys(gc).length?'  '+Object.entries(gc).map(([g,k])=>g+' '+k).join('  '):''}</div><div class="pr-bar" aria-hidden="true"><i style="width:${Math.round(n/N*100)}%"></i></div>
 <div class="his-grid gar"><div class="his-gh"><span>ลำดับ</span><span>เคสฝึกงาน</span><span>สถานะ</span><span></span></div>${L.map((x,i)=>{const d=D[x.id],cur=S.cs&&S.cs.id===x.id,g=prGate(x);
  const stt=d?`<i class="his-st ok">${d.g}</i>`:cur?'<i class="his-st go">กำลังทำ</i>':g?`<i class="his-st">บัตร ${g==='ruby'?'RUBY':'PEARL'}</i>`:'<i class="his-st">รอรับ</i>';
  const btn=d?`<button class="his-btn sm" data-h="nbc" data-v="${x.id}">เปิด</button>${!c?`<button class="his-btn sm" data-h="csacc" data-v="${x.id}">ทำซ้ำ</button>`:''}`:(!c&&!g?`<button class="his-btn sm pri" data-h="csacc" data-v="${x.id}">รับ</button>`:'');
  return `<div class="his-gr"><span><code>${i+1}</code></span><span><b>${esc(x.t)}</b><small>${x.type}  ระดับ ${x.lvl||1}${d?'  '+new Date(d.at).toLocaleDateString('th-TH')+'  '+Math.max(0,d.pts)+'/'+d.max:''}</small></span><span>${stt}</span><span>${btn}</span></div>`}).join('')}</div>`}
function prState(){S.pr=S.pr||{};S.pr.seen=S.pr.seen||{};return S.pr}
function prDoneN(){const D=S.csDone||{};return PR_IDS.filter(id=>D[id]).length}
function prGate(c){const i=PR_IDS.indexOf(c.id),t=gTier();return (i<=0||t>=1)?'':'ruby'}
function prLock(c){const i=PR_IDS.indexOf(c.id);return 'เคสฝึกงานที่ '+(i+1)+' สำหรับบัตร RUBY ขึ้นไป  บัตรฟรีเล่นได้เคสแรก บัตร RUBY และ PEARL เล่นได้ครบทุกเคส'}
function prInfo(){return 'เก็บเคสฝึกงาน '+prDoneN()+'/'+PR_IDS.length+'  บัตรฟรีเล่นได้เคสแรก บัตร RUBY ขึ้นไปเล่นได้ครบ'}
function prNext(){const D=S.csDone||{};const id=PR_IDS.find(x=>!D[x]);return id?CASES.find(c=>c.id===id):null}
function prPending(){if(S.cs)return false;const c=prNext();return !!c&&!prGate(c)}
function prTierOK(){return true}
function prMentor(b){const PS=prState(),sp=(t,fn)=>say(b.name,b.role,b.ap,t,fn);avRewardCheck();const n=prDoneN(),N=PR_IDS.length;
 if(n>=N){sp('เก็บเคสฝึกงานครบทั้ง '+N+' เคสแล้ว เก่งมาก ชุดนักศึกษาฝึกงานกับฉายา "ผ่านการฝึกงาน" อยู่ในหน้าแต่งตัว หมวดของรางวัล ถ้าอยากทบทวนเคสไหน เปิดดูได้ที่คอมพิวเตอร์ เมนูทะเบียนเคส');return}
 const c=prNext(),g=prGate(c),first=!PS.seen.intro;
 const intro='ยินดีต้อนรับสู่การฝึกงานที่โรงพยาบาลบ้านสุขใจนะ เป้าหมายของน้องคือเก็บเคสให้ครบ '+N+' เคส มีทั้งผู้รับบริการพูดอีสาน เหนือ ใต้ และแรงงานต่างชาติ ทุกเคสต้องแนะนำตัวว่าเป็นนักศึกษา ขอความยินยอม ใช้เครื่องมือประเมินให้ถูก และกลับมาปรึกษาพี่ก่อนตัดสินใจเรื่องสำคัญ\n\n';
 if(g){PS.seen.intro=1;save();sp((first?intro:'')+'เก็บเคสแล้ว '+n+' จาก '+N+' เคส  '+prLock(c));return}
 PS.seen.intro=1;save();const fr=TAGW[c.from]||'';
 openDlg({who:b.name,role:b.role,ap:b.ap,text:P((first?intro:'')+'เก็บเคสแล้ว '+n+' จาก '+N+' เคส\n\nเคสต่อไป: '+c.t+' ('+c.type+')\nส่งปรึกษาจาก'+fr+'\n\nจะรับเคสเลยไหม หรือเลือกเคสอื่นจากคอมพิวเตอร์ในห้องสังคมสงเคราะห์ก็ได้'),choices:[{t:'รับเคสนี้',fn:()=>{st.dlg=null;drawDlg();csAccept(c.id)}},{t:'ดูรายการเคสทั้งหมด',fn:()=>{st.dlg=null;drawDlg();pcPanel('inbox')}},{t:'ไว้ก่อน',fn:()=>{st.dlg=null;drawDlg()}}]})}
function prGrad(b){avRewardCheck()}
function prGo(){if(S.cs){const c=CASES.find(x=>x.id===S.cs.id);if(c&&!c.pr)toast('มีเคสค้างที่โรงพยาบาลธรรมราชบดินทร์อยู่ ปิดเคสนั้นก่อนจึงจะรับเคสฝึกงานได้')}loadCMH([5,5]);st.mode='play';screen();hud();draw();drawMini();MUSIC.play('house');setTimeout(()=>toast('โรงพยาบาลอนามัยชุมชน  พี่วอลส์รออยู่ที่ห้องสังคมสงเคราะห์ ชั้น 1'),300)}
function prFacTalk(b){openDlg({who:b.name,role:b.role,ap:b.ap,text:P('เปิดลงทะเบียนฝึกงานภาคปฏิบัติที่โรงพยาบาลบ้านสุขใจแล้วนะคะ เป็นโรงพยาบาลชุมชน มีพี่วอลส์เป็นพี่เลี้ยง ให้เก็บเคสฝึกงานให้ครบ '+PR_IDS.length+' เคส จะไปเลยไหมคะ'),choices:[{t:'ไปฝึกงานเลย',fn:()=>{st.dlg=null;drawDlg();prGo()}},{t:'ไว้ก่อน',fn:()=>{st.dlg=null;drawDlg()}}]})}
