 const lab=v.map((x,i)=>{const [X,Y]=pt(i,R+16);return `<text x="${X.toFixed(1)}" y="${(Y+3).toFixed(1)}" text-anchor="middle" font-size="9" font-weight="700" fill="#7A4A50">${x[0]}</text>`}).join('');
