const SWP_CALLS=[
 ['พยาบาลหอผู้ป่วยใน','หอผู้ป่วยชั้น 5','ญาติเตียง 12 ไม่ยอมรับผู้ป่วยกลับบ้าน บอกว่าไม่มีใครดูแล ช่วยลงมาคุยหน่อยได้ไหม',[['รับเรื่อง แล้วนัดคุยกับผู้ป่วยและญาติวันนี้',2,'ดีมาก การคุยร่วมกันทำให้เห็นทั้งความต้องการของผู้ป่วยและข้อจำกัดของครอบครัว'],['ขอให้พยาบาลอธิบายญาติไปก่อน แล้วค่อยโทรกลับ',1,'ยังช่วยได้ แต่ปัญหาผู้ดูแลเป็นงานของนักสังคมสงเคราะห์โดยตรง ควรเข้าไปประเมินเอง'],['แจ้งว่าแพทย์สั่งจำหน่ายแล้ว ญาติต้องรับกลับบ้าน',0,'การบังคับโดยไม่ประเมินอาจทำให้ผู้ป่วยกลับไปอยู่ในสภาพที่ไม่ปลอดภัย']]],
 ['แพทย์ห้องฉุกเฉิน','ห้องฉุกเฉิน','เด็กอายุ 9 ปี มีรอยช้ำหลายจุด ผู้ปกครองเล่าเหตุการณ์ไม่ตรงกัน',[['ประเมินร่วมกับทีมทันที และแจ้งศูนย์พึ่งได้',2,'ถูกต้อง กรณีสงสัยว่าเด็กถูกกระทำต้องประเมินความปลอดภัยและใช้ระบบคุ้มครองเด็กทันที'],['ขอให้แพทย์บันทึกบาดแผลไว้ก่อน แล้วค่อยตามไปดู',1,'การบันทึกบาดแผลสำคัญ แต่ความปลอดภัยของเด็กรอไม่ได้'],['ถามผู้ปกครองต่อหน้าเด็กเลยว่าใครเป็นคนทำร้าย',0,'การซักถามต่อหน้าเด็กอาจทำให้เด็กกลัวและเสี่ยงต่อการถูกทำร้ายซ้ำ']]],
 ['เจ้าหน้าที่การเงิน','ฝ่ายการเงินโรงพยาบาล','ผู้ป่วยไม่มีเงินจ่ายค่ารักษาส่วนเกิน ขอให้ช่วยประเมินหน่อย',[['นัดประเมินฐานะ และตรวจสอบสิทธิที่ผู้ป่วยมี',2,'ดีมาก หลายรายมีสิทธิที่ยังไม่ได้ใช้ หรือเข้าเกณฑ์ขอสงเคราะห์ค่ารักษา'],['แนะนำให้ญาติไปยืมเงินคนในครอบครัวมาจ่ายก่อน',1,'อาจช่วยได้บ้าง แต่ควรตรวจสอบสิทธิและแหล่งช่วยเหลือก่อน'],['ให้ผู้ป่วยเซ็นรับสภาพหนี้แล้วกลับบ้านได้',0,'การผลักภาระโดยไม่ประเมินฐานะไม่ใช่บทบาทของนักสังคมสงเคราะห์']]],
 ['เจ้าหน้าที่ รพ.สต.','รพ.สต.ใกล้บ้านผู้ป่วย','ขอข้อมูลผู้ป่วยที่เพิ่งกลับบ้าน เพื่อออกไปเยี่ยมบ้านพรุ่งนี้',[['ขอความยินยอมก่อน แล้วส่งข้อมูลเท่าที่จำเป็น',2,'ถูกต้อง การส่งต่อต้องได้รับความยินยอมและส่งเฉพาะข้อมูลที่ใช้ดูแลต่อ'],['ส่งสรุปสั้น ๆ ทางแชตส่วนตัวไปก่อน เพราะเร่งด่วน',1,'ตั้งใจดี แต่ต้องระวังช่องทางที่ไม่ปลอดภัยและต้องมีความยินยอมก่อน'],['ส่งแฟ้มประวัติทั้งหมดไปให้อ่านเองจะได้ครบถ้วน',0,'การส่งข้อมูลเกินจำเป็นละเมิดความลับของผู้ป่วย']]],
 ['ลูกสาวผู้ป่วย','ญาติผู้ป่วย','ไม่มีใครบอกอาการพ่อเลย ฉันโทรมาหลายรอบแล้ว',[['รับฟังความรู้สึก แล้วประสานแพทย์ให้อธิบาย',2,'ดีมาก รับฟังก่อนช่วยลดความโกรธ แล้วจึงเชื่อมให้ได้ข้อมูลจากผู้ที่ถูกต้อง'],['ขอโทษแทนทีม แล้วบอกให้รอแพทย์โทรติดต่อกลับไป',1,'สุภาพ แต่ยังไม่ได้ช่วยให้ญาติได้ข้อมูลจริง'],['บอกว่าไม่ใช่หน้าที่ ให้โทรไปถามหอผู้ป่วยเอาเอง',0,'การปัดความรับผิดชอบทำให้ญาติรู้สึกถูกทอดทิ้ง']]],
 ['พยาบาลหอผู้ป่วย','หอผู้ป่วยอายุรกรรม','ผู้ป่วยพูดว่าไม่อยากอยู่แล้ว ช่วยมาดูหน่อยได้ไหม',[['รีบไปพบ ประเมินความเสี่ยง แจ้งทีมเฝ้าระวัง',2,'ถูกต้อง คำพูดลักษณะนี้ต้องประเมินทันทีและให้ทีมดูแลใกล้ชิด'],['แนะนำให้พยาบาลส่งปรึกษาจิตแพทย์ตามระบบไปก่อน',1,'การส่งปรึกษาจำเป็น แต่ควรเข้าไปพบและประเมินด้วยตนเองด้วย'],['บอกว่าคงพูดไปเรื่อย ให้พยาบาลคอยสังเกตไปก่อน',0,'ไม่ควรมองข้าม ทุกคำพูดเรื่องไม่อยากมีชีวิตต้องได้รับการประเมิน']]],
 ['พยาบาลคัดกรอง','ห้องฉุกเฉิน','ผู้สูงอายุนอนรอที่ห้องฉุกเฉินมาหกชั่วโมง ไม่มีญาติมารับ',[['ติดตามญาติ และประสาน พมจ. หากไม่มีผู้ดูแล',2,'ดีมาก ตามหาเครือข่ายครอบครัวก่อน แล้วใช้ระบบคุ้มครองเมื่อไม่มีผู้ดูแล'],['ให้ผู้ป่วยรอต่อที่โถงจนกว่าจะมีคนมารับกลับ',1,'ยังปลอดภัยชั่วคราว แต่ไม่ได้แก้ปัญหา'],['เรียกแท็กซี่ส่งผู้ป่วยกลับตามที่อยู่ในบัตร',0,'อาจส่งผู้ป่วยกลับไปอยู่คนเดียวโดยไม่มีใครดูแล']]],
 ['เจ้าหน้าที่ตำรวจ','สถานีตำรวจในพื้นที่','ขอเข้าสัมภาษณ์ผู้ป่วยที่ถูกทำร้าย แต่ตอนนี้เขายังอ่อนเพลียอยู่',[['ถามความพร้อมผู้ป่วยก่อน ให้คนที่ไว้ใจอยู่ด้วย',2,'ถูกต้อง เคารพการตัดสินใจของผู้ป่วยและลดความหวาดกลัวระหว่างให้ปากคำ'],['ให้ตำรวจเข้าไปได้เลย แต่ขอให้คุยไม่เกินสิบนาที',1,'จำกัดเวลาได้ แต่ยังไม่ได้ถามความพร้อมของผู้ป่วย'],['ปฏิเสธตำรวจไปทันที โดยไม่ได้ถามผู้ป่วยก่อนเลย',0,'การตัดสินใจแทนผู้ป่วยไม่เคารพสิทธิของเขา']]],
 ['เจ้าหน้าที่เวชระเบียน','จุดลงทะเบียน','ผู้ป่วยแรงงานข้ามชาติไม่มีสิทธิรักษา และสื่อสารภาษาไทยได้น้อย',[['ขอล่ามช่วยสื่อสาร แล้วตรวจสอบสิทธิที่มี',2,'ดีมาก การสื่อสารที่เข้าใจตรงกันเป็นพื้นฐาน และบางรายมีประกันที่ใช้ได้'],['ใช้แอปแปลภาษาอธิบายเรื่องค่าใช้จ่ายไปก่อน',1,'ช่วยได้เบื้องต้น แต่เรื่องสำคัญควรมีล่ามที่แม่นยำ'],['ให้นายจ้างมารับผิดชอบทั้งหมดแล้วจบเรื่อง',0,'ไม่ได้ประเมินความต้องการและสิทธิของผู้ป่วยเลย']]],
 ['นักกายภาพบำบัด','หน่วยฟื้นฟู','ผู้ป่วยอัมพาตครึ่งซีกจะกลับบ้าน แต่ยังไม่มีบัตรคนพิการ',[['อธิบายสิทธิ แล้วนัดจดทะเบียนคนพิการ',2,'ถูกต้อง การจดทะเบียนช่วยให้เข้าถึงเบี้ยความพิการและอุปกรณ์'],['ให้ญาติไปถามที่สำนักงานเขตเองในภายหลัง',1,'ข้อมูลไม่ผิด แต่ญาติมักไม่รู้ขั้นตอนและอาจไม่ได้ทำ'],['บอกว่าต้องรอให้ครบหนึ่งปีจึงจะทำบัตรได้',0,'ข้อมูลไม่ถูกต้อง และทำให้ผู้ป่วยเสียโอกาสเข้าถึงสิทธิ']]],
 ['พี่เลี้ยง','นักสังคมสงเคราะห์พี่เลี้ยง','บันทึกเคสของวันนี้ยังไม่ครบนะ จะจัดการยังไง',[['บันทึกตามจริง แยกข้อเท็จจริงกับความเห็น',2,'ดีมาก บันทึกที่ดีต้องตรวจสอบได้และแยกสิ่งที่เห็นกับสิ่งที่คิด'],['รับปากว่าจะบันทึกให้ครบก่อนกลับบ้านวันนี้',1,'ตั้งใจดี แต่ควรบันทึกใกล้เวลาที่ทำงานจริงที่สุด'],['คัดลอกบันทึกเคสเก่ามาแล้วแก้ชื่อผู้ป่วย',0,'ผิดจริยธรรม บันทึกต้องสะท้อนผู้ป่วยรายนั้นจริง']]],
 ['ภรรยาผู้ป่วย','ญาติผู้ป่วยระยะท้าย','อยากพาสามีกลับไปใช้ช่วงสุดท้ายที่บ้าน ทำได้ไหม',[['ประชุมทีมกับครอบครัว วางแผนดูแลต่อที่บ้าน',2,'ถูกต้อง เคารพความปรารถนาและเตรียมการดูแลที่บ้านให้พร้อม'],['บอกว่าอยู่โรงพยาบาลปลอดภัยกว่า ให้คิดอีกที',1,'ห่วงใยได้ แต่ควรเคารพทางเลือกของผู้ป่วยและครอบครัว'],['ให้เซ็นไม่สมัครใจอยู่รักษาแล้วกลับได้เลย',0,'ขาดการเตรียมการ ผู้ป่วยอาจกลับไปโดยไม่มีการดูแลที่เหมาะสม']]]];

/* ===== v763 ระบบในเกมนักสังคมสงเคราะห์: ตั้งค่าเกม กล้องใกล้ กระเป๋าอุปกรณ์ แผนที่ใหญ่และหมุดนำทาง
   ป้ายชื่อ จอยสติ๊ก ปุ่มวิ่ง โทรศัพท์ในเกม ธีมปุ่มสีอ่อน และเพลงประกอบชุดใหม่ ===== */
const SWS_DEF={zoom:1.4,mus:70,sfx:80,musOn:true,ctrl:'pad',size:'m',side:'r',tap:true,names:'near',arrow:true,mini:'s',font:'m',run:false,phone:true};
