const SWP_USE={badge:['แนะนำตัวกับ{n}แล้ว บอกชื่อ บทบาท และเหตุผลที่มาพบ','ติดบัตรเรียบร้อย พร้อมแนะนำตัวกับผู้รับบริการ'],
 clip:['เริ่มคัดกรองกับ{n} ถามปัญหาและความต้องการเบื้องต้น','เข้าไปใกล้ผู้รับบริการ แล้วใช้แบบคัดกรองอีกครั้ง'],
 folder:['เปิดแฟ้มของ{n} ดูเฉพาะข้อมูลที่จำเป็นต่อการช่วยเหลือ','แฟ้มเก็บเป็นความลับ เปิดเมื่ออยู่กับผู้รับบริการหรือทีมเท่านั้น'],
 geno:['ชวน{n}วาดผังครอบครัวร่วมกัน เห็นว่าใครพอช่วยดูแลได้','เข้าไปใกล้ผู้รับบริการเพื่อวาดผังครอบครัวร่วมกัน'],
 eco:['ทำแผนที่นิเวศกับ{n} เห็นแหล่งช่วยเหลือรอบตัว','เข้าไปใกล้ผู้รับบริการเพื่อทำแผนที่นิเวศร่วมกัน'],
 magn:['ประเมินองค์รวมกับ{n} ทั้งร่างกาย จิตใจ สังคม และเศรษฐกิจ','เข้าไปใกล้ผู้รับบริการเพื่อประเมินองค์รวม'],
 form:['อธิบายใบยินยอมให้{n}ฟังจนเข้าใจ ก่อนส่งข้อมูลต่อ','ใบยินยอมต้องให้ผู้รับบริการอ่านหรือฟังจนเข้าใจก่อนลงชื่อ'],
 bag:['ตรวจกระเป๋าเยี่ยมบ้านแล้ว มีแบบประเมินและเอกสารครบ','ตรวจกระเป๋าเยี่ยมบ้านแล้ว มีแบบประเมินและเอกสารครบ'],
 cal:['นัดติดตามกับ{n}แล้ว จดวันและช่องทางติดต่อให้ชัด','บันทึกวันนัดติดตามในปฏิทินแล้ว'],
 stamp:['ทบทวนเป้าหมายกับ{n}ก่อนปิดเคส ว่าบรรลุแล้วจริง','ปิดเคสได้เมื่อบรรลุเป้าหมายร่วมกับผู้รับบริการ'],
 medal:['เข็มเกียรติคุณติดอยู่ที่ปกเสื้อ','เข็มเกียรติคุณติดอยู่ที่ปกเสื้อ']};
function swpNote(t){S.swNotes=S.swNotes||[];const d=new Date();S.swNotes.unshift({t,at:d.getTime(),p:(st&&st.room)||''});if(S.swNotes.length>60)S.swNotes.length=60;try{save()}catch(e){}}
function swpKitPanel(sel){try{swhCss()}catch(e){}const L=swKitList(),n=L.filter(x=>x.ok).length;S.swKitSeen=n;try{save()}catch(e){}const x=sel!=null?L[sel]:null;
 openHP('กระเป๋านักสังคมสงเคราะห์ '+n+'/'+L.length,`<p class="zsw-p">อุปกรณ์ที่ใช้ทำงานจริง แตะเพื่อดูวิธีใช้ ถ้ายืนใกล้ใครอยู่ กดใช้แล้วจะได้ใช้กับคนนั้น</p><div class="swh-kit">${L.map((y,i)=>`<button type="button" data-sw="kitp" data-v="${i}" class="${y.ok?'':'lk'}${sel===i?' on':''}">${swI(y.k)}<small>${y.n}</small></button>`).join('')}</div>${x?`<div class="swh-kd">${swI(x.k)}<div><b>${x.n}${x.ok?'':' (ยังไม่ได้รับ)'}</b><small>${x.ok?x.d:'ปลดล็อกเมื่อ'+x.need}</small></div></div>${x.ok?`<div class="sw-use"><button type="button" data-sw="use" data-v="${sel}">ใช้${x.n}</button></div>`:''}`:''}`,'sw-p sw-kitp')}
function swpUse(i){const x=swKitList()[i];if(!x||!x.ok)return;const t=near();const nm=t?(t.bot?t.bot.name:t.npc&&DAY&&DAY.npcs&&DAY.npcs[t.key]?DAY.npcs[t.key].name:''):'';
 if(x.k==='note'){const N=S.swNotes||[];openHP('สมุดบันทึกภาคสนาม',`<p class="zsw-p">บันทึกที่จดไว้ระหว่างใช้อุปกรณ์ในเกม ใช้ทบทวนก่อนเขียนรายงาน</p>${N.length?`<ul class="sw-notes">${N.slice(0,30).map(o=>{const d=new Date(o.at);return `<li><small>${d.getDate()}/${d.getMonth()+1} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}${o.p?' '+esc(o.p):''}</small>${esc(o.t)}</li>`}).join('')}</ul>`:'<p class="zsw-p">ยังไม่มีบันทึก ลองใช้อุปกรณ์ชิ้นอื่นกับผู้รับบริการดูก่อน</p>'}`,'sw-p sw-kitp');return}
 if(x.k==='law'){openHP('คู่มือกฎหมายสวัสดิการ',`<ul class="swh-ls">${SWH_LAW.map(([a,b])=>`<li>${swI('law')}<div><b>${a}</b><small>${b}</small></div></li>`).join('')}</ul>`,'sw-p sw-kitp');return}
 if(x.k==='net'){const cd=Object.keys(S.csDone||{}).length;openHP('สมุดรายชื่อเครือข่าย',`<ul class="swh-ls">${SWH_NET.filter(y=>cd>=y[3]).map(([a,tel,w])=>`<li>${swI(tel?'phone':'net')}<div><b>${a}</b><small>${w}</small>${tel?`<span class="swh-tel">สายด่วน ${tel}</span>`:''}</div></li>`).join('')}</ul>`,'sw-p sw-kitp');return}
 if(x.k==='phone'){closeHP();if(typeof zgPb==='function'&&(st.hosp||st.hv)){try{zgPb(1);return}catch(e){}}toast('โทรศัพท์พร้อมใช้ ประสานหน่วยงานได้เมื่ออยู่ในเคส');return}
 if(x.k==='mug'){closeHP();const k='swMug'+isoD(new Date());if(S[k]){toast('วันนี้พักดื่มชาไปแล้ว พรุ่งนี้ค่อยพักใหม่');return}S[k]=1;if(typeof st.energy==='number')st.energy=Math.min(100,st.energy+15);if(typeof st.stress==='number')st.stress=Math.max(0,st.stress-10);try{save()}catch(e){}toast('พักจิบชาสักครู่ พลังงานเพิ่มขึ้น ความเครียดลดลง');swpNote('พักดื่มชา ดูแลตัวเองระหว่างวัน');return}
 const U=SWP_USE[x.k]||['ใช้'+x.n+'กับ{n}แล้ว','ใช้'+x.n+'แล้ว'];const msg=nm?U[0].replace(/\{n\}/g,nm):U[1];closeHP();toast(msg);if(nm)swpNote(msg)}

/* ---------- แผนที่ใหญ่และหมุดนำทาง ---------- */
function swpPlace(){return swpHome()?'บ้านของฉัน':st.hv?'เยี่ยมบ้าน':MAP&&MAP.uh?'ศูนย์การแพทย์ ชั้น '+st.floor:MAP&&MAP.court?'ศาลเยาวชนฯ ชั้น '+st.floor:MAP&&MAP.cmh?'บ้านสุขใจ':st.hosp?'โรงพยาบาลจังหวัด ชั้น '+st.floor:st.fac?'คณะ':(DAY&&DAY.place)||'แผนที่'}
function swpMapPanel(){if(!MAP)return;const R=[];(MAP.rooms||[]).forEach((r,i)=>{if(r[0]&&!R.some(x=>x[0]===r[0]))R.push([r[0],i])});const here=st.room||'';
 const lift=!!(MAP.uh||MAP.court||MAP.cmh||st.hosp);
 openHP('แผนที่ '+swpPlace(),`<div class="sw-mapw"><canvas data-swmap="1" aria-label="แผนที่ แตะตำแหน่งเพื่อปักหมุดและเดินไป"></canvas></div><div class="sw-lgd"><span><i style="background:#E31414"></i>ตัวเรา</span><span><i style="background:#FFD000"></i>งานที่ต้องทำ</span><span><i style="background:#FF8A00"></i>เคสแทรก</span></div><p class="sw-mapn">แตะบนแผนที่หรือเลือกชื่อห้อง ระบบจะปักหมุดและพาเดินไปเอง</p>${R.length?`<div class="sw-rooms">${R.map(([n,i])=>`<button type="button" data-sw="room" data-v="${i}" class="${n===here?'here':''}">${esc(n)}</button>`).join('')}</div>`:''}${lift?`<div class="sw-acts" style="margin-top:10px"><button type="button" class="dg" data-sw="lift">${swI('lift')} ลิฟต์ เปลี่ยนชั้น</button><button type="button" data-sw="unpin">ยกเลิกหมุด</button></div>`:`<div class="sw-acts" style="margin-top:10px"><button type="button" data-sw="unpin">ยกเลิกหมุด</button></div>`}`,'sw-p sw-mapp');
 const c=root.querySelector('canvas[data-swmap]');if(!c)return;const _m=mm;mm=c;try{drawMini()}catch(e){}mm=_m;if(st.swPin){const g=c.getContext('2d');g.fillStyle='#E31414';g.fillRect(st.swPin.x*3-2,st.swPin.y*3-2,7,7);g.fillStyle='#fff';g.fillRect(st.swPin.x*3,st.swPin.y*3,3,3)}
 c.addEventListener('click',e=>{const r=c.getBoundingClientRect();const x=Math.floor((e.clientX-r.left)/r.width*MAP.w),y=Math.floor((e.clientY-r.top)/r.height*MAP.h);swpGo(x,y,roomAt(x,y)||'จุดที่เลือก')})}
function swpGo(x,y,n){const m=st.me;const p=bfs(m.x,m.y,(a,b)=>Math.abs(a-x)+Math.abs(b-y)<=1);if(!p){toast('ไปตรงนั้นไม่ได้ ลองเลือกจุดอื่น');return}closeHP();st.swPin={x,y,n};m.path=p;m.after=null;st.tap={x,y,t:performance.now()};toast('กำลังเดินไป'+n)}
function swpRoom(i){const r=MAP.rooms[i];if(!r)return;const m=st.me;const p=bfs(m.x,m.y,(a,b)=>a>=r[1]&&a<=r[3]&&b>=r[2]&&b<=r[4]);if(!p){toast('ไป'+r[0]+'ไม่ได้จากตรงนี้');return}closeHP();const cx=Math.round((r[1]+r[3])/2),cy=Math.round((r[2]+r[4])/2);st.swPin={x:cx,y:cy,n:r[0]};m.path=p;m.after=null;toast('กำลังเดินไป'+r[0])}

/* ---------- ตั้งค่าเกม ---------- */
function swpSeg(k,opts){return `<div class="sw-seg">${opts.map(([v,l])=>`<button type="button" data-sw="opt" data-k="${k}" data-v="${v}" class="${String(SWS[k])===String(v)?'on':''}">${l}</button>`).join('')}</div>`}
function swpSetPanel(){const sec=(ic,t,b)=>`<section class="sw-sec"><h5>${swI(ic)}${t}</h5>${b}</section>`,row=(t,b)=>`<div class="sw-row"><span>${t}</span>${b}</div>`;
 openHP('ตั้งค่าเกม',`<div class="sw-set">
 ${sec('magn','ภาพ',row('ระยะกล้อง',swpSeg('zoom',SWS_ZL))+row('เต็มจอ',`<div class="sw-seg"><button type="button" data-sw="fs" class="${S.gfs===true?'on':''}">เปิด</button><button type="button" data-sw="fs" class="${S.gfs===true?'':'on'}">ปิด</button></div>`)+row('แผนที่ย่อ',swpSeg('mini',[['off','ซ่อน'],['s','เล็ก'],['l','ใหญ่']]))+row('ป้ายชื่อเหนือหัว',swpSeg('names',[['near','เมื่อเข้าใกล้'],['all','ทุกคน'],['off','ปิด']]))+row('ลูกศรนำทางไปงานถัดไป',swpSeg('arrow',[['true','เปิด'],['false','ปิด']])))}
 ${sec('mug','เสียง',row('เพลงประกอบ',`<label class="sw-rg"><input type="range" min="0" max="100" value="${SWS.mus}" data-swr="mus" aria-label="ความดังเพลง"><b>${SWS.mus}</b></label>`)+row('เปิดเพลง',swpSeg('musOn',[['true','เปิด'],['false','ปิด']]))+row('เสียงประกอบ',`<label class="sw-rg"><input type="range" min="0" max="100" value="${SWS.sfx}" data-swr="sfx" aria-label="ความดังเสียงประกอบ"><b>${SWS.sfx}</b></label>`))}
 ${sec('run','การควบคุม',row('ปุ่มเดิน',swpSeg('ctrl',[['pad','ปุ่มลูกศร'],['joy','จอยสติ๊ก']]))+row('ขนาดปุ่ม',swpSeg('size',[['s','เล็ก'],['m','กลาง'],['l','ใหญ่']]))+row('ปุ่มกดอยู่ด้าน',swpSeg('side',[['r','ขวา'],['l','ซ้าย']]))+row('แตะพื้นเพื่อเดินไปเอง',swpSeg('tap',[['true','เปิด'],['false','ปิด']]))+row('วิ่งเร็ว',swpSeg('run',[['true','เปิด'],['false','ปิด']])))}
 ${sec('talk','ข้อความและการแจ้งเตือน',row('ขนาดตัวอักษรในบทสนทนา',swpSeg('font',[['m','ปกติ'],['l','ใหญ่'],['xl','ใหญ่มาก']]))+row('สายเข้าระหว่างเล่น',swpSeg('phone',[['true','เปิด'],['false','ปิด']])))}
 ${sec('note','วิธีเล่น',`<ol class="sw-how"><li>เดินด้วยปุ่มลูกศรหรือจอยสติ๊ก หรือแตะพื้นเพื่อเดินไปเอง</li><li>เข้าใกล้คนหรือสิ่งของ ปุ่มวงกลมจะบอกว่าทำอะไรได้ แล้วกดเพื่อคุย สังเกต หรือใช้งาน</li><li>ปุ่มแผนที่ใช้ปักหมุดห้องที่อยากไป ระบบจะพาเดินไปและชี้ลูกศรให้</li><li>ปุ่มกระเป๋ามีอุปกรณ์นักสังคมสงเคราะห์ ยืนใกล้ผู้รับบริการแล้วกดใช้ได้</li><li>มีสายเข้าเป็นระยะ ตอบให้เหมาะสมเพื่อรับเหรียญ</li></ol>`)}
 <div class="sw-acts"><button type="button" data-sw="status">สถานะงานวันนี้</button><button type="button" data-sw="reset">คืนค่าเริ่มต้น</button><button type="button" data-sw="week">กลับเมนูเกม</button><button type="button" class="dg" data-sw="exit">ออกจากเกม</button></div></div>`,'sw-p sw-setp')}
function swpOpt(k,v){if(v==='true')v=true;else if(v==='false')v=false;else if(k==='zoom')v=+v;SWS[k]=v;swsSave();swpApply();const sc=root.querySelector('.g-hp .hp-bd');const top=sc?sc.scrollTop:0;swpSetPanel();const sc2=root.querySelector('.g-hp .hp-bd');if(sc2)sc2.scrollTop=top}
document.addEventListener('input',e=>{const r=e.target.closest&&e.target.closest('[data-swr]');if(!r)return;const k=r.dataset.swr;SWS[k]=+r.value;const b=r.parentNode.querySelector('b');if(b)b.textContent=r.value;swsSave();try{SWZ.vol(SWS.mus/100,SWS.sfx/100,SWS.musOn)}catch(x){}});
document.addEventListener('change',e=>{const r=e.target.closest&&e.target.closest('[data-swr="sfx"]');if(r)try{SWZ.jingle('good')}catch(x){}});

/* ---------- โทรศัพท์ในเกม ---------- */
function swpPhoneOK(){return SWS.phone!==false&&st&&st.mode==='play'&&!st.dlg&&!swpHome()&&!st.ended&&root&&root.querySelector('.g-hp')&&root.querySelector('.g-hp').hidden&&(st.hosp||(MAP&&(MAP.uh||MAP.cmh))||(DAY&&typeof DAY.n==='number'))}
function swpPhoneTick(vis){if(!vis||!st)return;const now=Date.now();if(st.swCall){if(now-st.swCall.at>50000){st.swCall=null;toast('สายหลุดไปแล้ว เดี๋ยวจะมีสายเข้ามาใหม่');swpPhoneUI()}return}
 if(!swpPhoneOK())return;if(!swpPlayT0||now-swpPlayT0<70000)return;if(now-swpPhLast<170000)return;if(Math.random()>.04)return;
 const done=(S.swPh&&S.swPh.seen)||[];let pool=SWP_CALLS.map((c,i)=>i).filter(i=>done.indexOf(i)<0);if(!pool.length)pool=SWP_CALLS.map((c,i)=>i);const i=pool[Math.floor(Math.random()*pool.length)];
 st.swCall={i,at:now};swpPhLast=now;toast('มีสายเข้า แตะโทรศัพท์เพื่อรับสาย');try{SWZ.jingle('phone')}catch(e){}swpPhoneUI()}
function swpPhoneUI(){if(!root)return;const sg=root.querySelector('.g-stage');if(!sg)return;let b=sg.querySelector('.sw-ph');const on=!!(st&&st.swCall&&st.mode==='play');
 if(on&&!b){b=document.createElement('button');b.type='button';b.className='sw-ph';b.dataset.sw='call';b.setAttribute('aria-label','รับสาย');b.innerHTML=swI('phone')+'<small>รับสาย</small>';sg.appendChild(b)}else if(!on&&b)b.remove()}
function swpAnswer(){const C=st.swCall;if(!C)return;st.swCall=null;swpPhoneUI();const c=SWP_CALLS[C.i];const ap=AP({hs:'bob',shirt:'#9BB8E8',skin:'#EBC09A'});
 const opts=shuffle(c[3].map(o=>o));openDlg({who:c[0],role:'สายเข้า '+c[1],ap,text:c[2]+'\nจะตอบอย่างไร',choices:opts.map(o=>({t:o[0],fn:()=>{st.dlg=null;const sc=o[1],coin=sc===2?8:sc===1?3:0;
  S.swPh=S.swPh||{n:0,ok:0,seen:[]};S.swPh.n++;if(sc===2)S.swPh.ok++;if(S.swPh.seen.indexOf(C.i)<0)S.swPh.seen.push(C.i);if(S.swPh.seen.length>=SWP_CALLS.length)S.swPh.seen=[];if(coin)S.coins=(S.coins||0)+coin;try{save()}catch(e){}
  try{SWZ.jingle(sc===2?'ex':sc===1?'good':'improve')}catch(e){}swpNote('รับสายจาก'+c[0]+' '+o[0]);
  say(c[0],sc===2?'ตอบได้ดีมาก':sc===1?'ยังพอใช้ได้':'ควรปรับปรุง',ap,o[2]+(coin?'\n\nได้รับ '+coin+' เหรียญ':''),null)}}))})}

/* ---------- คลิกทั้งหมดของระบบนี้ ---------- */
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-sw]');if(!b||!root||!root.contains(b))return;e.preventDefault();e.stopPropagation();const a=b.dataset.sw,v=b.dataset.v;
 if(a==='set')swpSetPanel();else if(a==='kit')swpKitPanel(null);else if(a==='kitp')swpKitPanel(+v);else if(a==='use')swpUse(+v);else if(a==='map')swpMapPanel();else if(a==='room')swpRoom(+v);
 else if(a==='unpin'){st.swPin=null;closeHP();toast('ยกเลิกหมุดแล้ว')}else if(a==='lift'){closeHP();try{liftPanel()}catch(x){}}
 else if(a==='opt')swpOpt(b.dataset.k,v);else if(a==='fs'){const want=b.textContent.trim()==='เปิด';if((S.gfs===true)!==want){S.gfs=want;try{save()}catch(x){}closeHP();applyFS();setTimeout(()=>{sizeCanvas();try{draw()}catch(x){}},120)}}
 else if(a==='reset'){SWS=Object.assign({},SWS_DEF);swsSave();swpApply();swpSetPanel();toast('คืนค่าเริ่มต้นแล้ว')}
 else if(a==='status'||a==='week'||a==='exit'){closeHP();const sel=a==='status'?'[data-h="menu"]':a==='week'?'[data-g="week"]':'[data-g="exit"]';const t=root.querySelector('.g-hud '+sel)||root.querySelector(sel);if(t)t.click();else if(a==='exit')try{go('more')}catch(x){}}
 else if(a==='run'){SWS.run=!SWS.run;swsSave();b.setAttribute('aria-pressed',String(SWS.run));toast(SWS.run?'โหมดวิ่งเปิดแล้ว':'กลับมาเดินปกติ')}
 else if(a==='call')swpAnswer()},true);

