function swMusWant(){if(!root||!root.isConnected||!root.offsetParent)return null;if(!st)return 'hub';
 if(st.mode!=='play')return st.mode==='intro'?'case':'hub';
 const cl=st.clock||0,rm=st.room||'';
 if(swpHome())return (cl>=1200||cl<360)?'housen':'house';
 if(st.hv||MK==='village')return 'village';
 if(MAP&&MAP.court)return 'court';
 if(st.night||((st.hosp||MK==='hospital')&&cl>=1110))return 'night';
 if(/ฉุกเฉิน|ICU|CCU|วิกฤต|ผ่าตัด/.test(rm))return 'er';
 if(/สัมภาษณ์|สังคมสงเคราะห์|ให้คำปรึกษา/.test(rm))return 'room';
 if(MAP&&MAP.uh)return 'uh';
 if(MAP&&MAP.cmh)return 'cmh';
 if(st.hosp){const f=st.floor||1;return {1:'opd',2:'er',3:'mch',4:'opd',5:'ward',6:'pall',7:'admin'}[f]||'opd'}
 if(st.fac||st.campus)return /ห้องเรียน|ห้องบรรยาย/.test(rm)?'class':'campus';
 if(DAY&&DAY.n===7)return 'homeend';if(DAY&&DAY.n===4)return 'meet';if(MK==='home')return 'homeend';
 return DAY&&DAY.n===1?'case':'ward'}
