if(!window.__swzT)window.__swzT=setInterval(()=>{try{swpOldMus();if(!window.SWZ)return;const w=swMusWant();SWZ.set(SWS.musOn===false?null:w);SWZ.duck(!!(st&&st.dlg));swpPhoneTick(w)}catch(e){}},600);
document.addEventListener('pointerdown',()=>{try{if(window.SWZ&&swMusWant()){SWZ.vol(SWS.mus/100,SWS.sfx/100,SWS.musOn);SWZ.unlock()}}catch(e){}},true);
