function dutyTick(){if(!st||!st.bots||!MAP)return;const m=st.clock,H=MAP.home||[MAP.start];
  st.bots.forEach(b=>{if(!b.duty)return;const on=!!b.duty(m);
    if(on&&b.off){b.off=false;b.hidden=false;b.leaving=false;const h=H[Math.floor(Math.random()*H.length)];b.x=h[0];b.y=h[1];b.px=b.x*T;b.py=b.y*T;b.mv=0;b.ri=0;b.pose='';b.wait=0;
      const r=b.route?b.route[0]:null;const tg=r?{x:r[0],y:r[1],dw:r[2],pose:r[3],dir:r[4],bub:r[5]}:(()=>{const p=randTile(b.wander);return {x:p[0],y:p[1],dw:1500,pose:'',dir:null,bub:''}})();
      const pp=b.instant?null:bfsB(b.x,b.y,tg.x,tg.y);if(b.csWho&&!b.instant&&st.hosp)toast(b.name+' มาถึงแล้ว  '+(CSLOT[b.id.split('_').slice(2).join('_')]||[])[5]);if(!pp){b.x=tg.x;b.y=tg.y;b.px=b.x*T;b.py=b.y*T}b.path=pp||[];b.arrive=tg;if(!b.path.length){b.arrive=null;b.arrived=tg}}
    else if(!on&&!b.off&&(b.instant||b.csWho)){b.off=true;b.hidden=true;b.leaving=false;b.path=[];b.mv=0}
    else if(!on&&!b.off&&!b.leaving){b.leaving=true;const h=H[Math.floor(Math.random()*H.length)];b.pose=b.pose==='bed'?'':b.pose==='sit'?'':b.pose;b.wait=0;b.bub='';
      const tg={x:h[0],y:h[1],dw:0,pose:'off'};b.path=bfsB(b.x,b.y,h[0],h[1])||[];b.arrive=tg;if(!b.path.length){b.arrive=null;b.arrived=tg}}});
  if(st.hosp)csTick()}
