const CXP=(c,g)=>Math.round((c.xp||{1:20,2:30,3:45,4:90}[c.lvl||2]||30)*({'ดีเยี่ยม':1.3,'ดี':1.1,'พอใช้':.9,'ต้องพัฒนา':.6}[g]||1));
function swXP(){const D=S.csDone||{};let x=0;CASES.forEach(c=>{if(D[c.id])x+=CXP(c,D[c.id].g)});return isPearl()?Math.round(x*1.2):x}
function swXPRank(x){x=x==null?swXP():x;let r=0;SWR.forEach((R,i)=>{if(x>=R.xp)r=i});return r}
function swRankI(x){const xr=swXPRank(x);if(S.swGateV!==1){S.swGateV=1;S.swHold=Math.max(S.swHold||0,xr)}let r=0;for(let i=1;i<=xr;i++){if(swGateOK(i))r=i;else break}return Math.max(r,Math.min(S.swHold||0,xr))}
const CS_ALL=['code:a994a790aaf34ccb'];function csAllOK(){return CS_ALL.includes(META.current)}function csN(){return CASES.filter(c=>!c.pr&&(!c.only||csAllOK())).length}
function swRank(){let R=SWR[swRankI()];if(csAllOK()&&R.lvl<4)R=Object.assign({},R,{lvl:4});return isPearl()?Object.assign({},R,{hint:Math.max(R.hint,1),retake:1}):R}
const swTitle=R=>'นักสังคมสงเคราะห์'+R.n;
function csHintsLeft(){return S.cs?Math.max(0,swRank().hint-(S.cs.hu||0)):0}
function csDgLeft(){return S.cs?Math.max(0,swRank().dg-(S.cs.dg||0)):0}
function csDelegate(){const s=csStep();if(!s||(s.k!=='read'&&s.k!=='form')||csDgLeft()<1)return;S.cs.dg=(S.cs.dg||0)+1;if(s.k==='form'){S.cs.pts+=2*s.f.length;S.cs.max+=2*s.f.length}closeHP();csDone(s);toast('ผู้ช่วยทำงานเอกสารให้เรียบร้อย');pcPanel('now')}
function csWarp(){const f=csFloorHint();if(!f||!swRank().warp)return;closeHP();loadHospFree(f,null);screen();hud();draw();drawMini();toast('ลิฟต์ด่วนไปชั้น '+f)}
function cvTabOld(){const x=swXP(),ri=swRankI(x),R=SWR[ri],N=SWR[ri+1],D=S.csDone||{},L=CASES.filter(c=>D[c.id]);const pct=N?Math.round((x-R.xp)/(N.xp-R.xp)*100):100;
  const gc={};L.forEach(c=>{gc[D[c.id].g]=(gc[D[c.id].g]||0)+1});const G=[['ดีเยี่ยม','#E31414'],['ดี','#FF7F8C'],['พอใช้','#F7B9C0'],['ต้องพัฒนา','#D3D8E0']];
  const C=2*Math.PI*44,off=C*(1-pct/100);const tc=csN(),hd=L.filter(c=>c.lvl===4).length,ty={};L.forEach(c=>{ty[c.type]=(ty[c.type]||0)+1});
  const ck='<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12l5 5 9-10"/></svg>';
  const lk='<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
  return `<div class="cv2-hero"><div class="cv2-ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="44" fill="none" stroke="#F3E3E6" stroke-width="8"/><circle cx="50" cy="50" r="44" fill="none" stroke="url(#cvg)" stroke-width="8" stroke-linecap="round" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}" transform="rotate(-90 50 50)"/><defs><linearGradient id="cvg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FF8A95"/><stop offset="1" stop-color="#E31414"/></linearGradient></defs></svg><span><b>${ri+1}</b><small>จาก ${SWR.length}</small></span></div>
    <div class="cv2-id"><small>ตำแหน่งปัจจุบัน</small><b>${swTitle(R)}</b><span class="cv2-xp"><em>${x.toLocaleString()}</em> XP</span><span class="cv2-nx">${N?(x>=N.xp?'XP ครบแล้ว ผ่านเงื่อนไขการเรียนเพื่อเลื่อนเป็น <b>'+N.n+'</b>':'อีก '+(N.xp-x).toLocaleString()+' XP และผ่านเงื่อนไขการเรียน เลื่อนเป็น <b>'+N.n+'</b>'):'ถึงตำแหน่งสูงสุดในสายงานแล้ว'}</span></div></div>
   ${N&&x>=N.xp&&!swGateOK(ri+1)?`<div class="cv2-wait"><b>รอผ่านเงื่อนไขการเรียน</b><small>ประสบการณ์พอเลื่อนเป็น${N.n}แล้ว ทำเงื่อนไขด้านล่างให้ครบ ตำแหน่งจะเลื่อนทันที</small></div>`:''}${N?swGateHTML(ri+1,'full'):''}
   <div class="cv2-kpi"><span><b>${L.length}<small>/${tc}</small></b>เคสที่ปิด</span><span><b>${hd}</b>เคสซับซ้อน</span><span><b>${L.length?Math.round((gc['ดีเยี่ยม']||0)/L.length*100):0}<small>%</small></b>ผลดีเยี่ยม</span></div>
   <div class="cv2-box"><div class="cv2-bh"><b>ผลการประเมินเคส</b><small>${L.length} เคส</small></div><div class="cv2-stk">${L.length?G.map(([g,c])=>gc[g]?`<i style="flex:${gc[g]};background:${c}"></i>`:'').join(''):'<i style="flex:1;background:#EEF2F8"></i>'}</div><div class="cv2-lg">${G.map(([g,c])=>`<span><i style="background:${c}"></i>${g} <b>${gc[g]||0}</b></span>`).join('')}</div>
    <div class="cv2-ty">${['บุคคล','ครอบครัว','กลุ่ม','ชุมชน'].map(t=>`<span><b>${ty[t]||0}</b>${t}</span>`).join('')}</div></div>
   <div class="cv2-box"><div class="cv2-bh"><b>เส้นทางสายงาน</b><small>นักสังคมสงเคราะห์</small></div>
    <ol class="cv2-lad">${SWR.map((r,i)=>`<li class="${i<ri?'ok':i===ri?'now':'lock'}"><span class="cv2-nd">${i<ri?ck:i===ri?i+1:lk}</span><div class="cv2-it"><div class="cv2-ih"><b>${r.n}</b><span>${i===0?'เริ่มต้น':r.xp.toLocaleString()+' XP'}</span></div>${i===ri?'<em class="cv2-now">ตำแหน่งปัจจุบัน</em>':''}<ul>${r.p.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>${i>ri+1?swGateHTML(i,'mini'):''}</div></li>`).join('')}</ol></div>
   <p class="his-hint">ประสบการณ์ได้จากการปิดเคส เคสซับซ้อนและผลประเมินดีได้มากกว่า ทุกตำแหน่งต้องผ่านเงื่อนไขการเรียนในแอปด้วย ตำแหน่งที่ได้แล้วจะไม่ถูกลดลง</p>`}

