const TAGA=new Set(["@kd","@pdn","@cin","@paln","@ger","@acpn","@mbn","@nicun","@anc","@kdn","@lr","@psn","@fin","@supv","@por","@ccun","@pacu","@eyen","@entn","@wnd","@dent","@mdn","@ck","@fc"]),CSHIDE={"1:9,22":"er","6:43,1":"ch","6:39,17":"acp","6:40,17":"acp","6:41,17":"acp","6:42,18":"acp","6:38,26":"acp","3:15,24":"teen","3:15,19":"ps","3:16,19":"ps","3:18,19":"ps","3:19,19":"ps","3:40,14":"picu","3:41,16":"picu","3:28,1":"lr","7:20,6":"fin","7:21,6":"fin","4:38,27":"ent","1:24,36":"rx"};

function CS(){return S.cs?CASES.find(c=>c.id===S.cs.id):null}
function csStep(){const c=CS();return c?c.steps[S.cs.i]:null}
function csWhere(){const c=CS();if(!c)return {};const w={};for(let i=0;i<=S.cs.i&&i<c.steps.length;i++){const s=c.steps[i];if(!s.show)continue;if(i===S.cs.i&&s.k==='escort'){for(const q in s.show)if(!(q in w))w[q]=s.show[q]}else Object.assign(w,s.show)}const s=csStep();if(S.cs.esc&&s&&s.who)w[s.who]=null;return w}
function csBusy(p){return Object.values(csWhere()).some(v=>v&&v.indexOf(p)===0)}
function csPerson(k){const c=CS();if(!c)return {n:'',r:'',ap:{}};if(k==='pt')return {n:c.pt.n,r:'ผู้ป่วย  '+c.pt.dx,ap:c.pt.ap||{}};const p=c.ppl[k]||{n:k,r:''};return {n:p.n,r:p.r,ap:p.ap||{}}}
function csIsTarget(k){const s=csStep();return !!s&&((s.k==='talk'&&s.who===k)||(s.k==='escort'&&s.who===k&&!S.cs.esc))}
function staffAlert(t){const s=csStep();if(!S.cs)return t==='@hn';return !!s&&((s.k==='talk'&&s.who===t)||(s.k==='escort'&&S.cs.esc&&s.to===t))}
function csActNow(){const s=csStep();if(!s)return null;if(s.k==='read'||s.k==='form'||s.k==='close')return ['pc','nurse','desk','swdesk'];if(s.k==='phone')return ['phone'];return null}
function csLoc(k){const v=csWhere()[k];return v&&CSLOT[v]?CSLOT[v][5]:'ยังไม่มาถึง'}
function csLine(){if(!S.cs)return MAP&&MAP.cmh?'ยังไม่มีเคส  รับเคสจากพี่วอลส์ หรือคอมพิวเตอร์ห้องสังคมสงเคราะห์ ชั้น 1':'ยังไม่มีเคส  รับเคสที่คอมพิวเตอร์ หรือหัวหน้าพยาบาล ชั้น 5';const s=csStep();if(!s)return '';
  const nm=k=>k.indexOf('@')===0?TAGW[k]:csPerson(k).n+'  '+csLoc(k);
  if(s.k==='talk')return 'คุยกับ'+nm(s.who);if(s.k==='read')return 'อ่านประวัติเคสในคอมพิวเตอร์';if(s.k==='form')return 'กรอก'+s.title+'ในคอมพิวเตอร์';
  if(s.k==='phone')return 'โทรศัพท์ที่ห้องสังคมสงเคราะห์  '+s.goal;if(s.k==='wait'){const l=Math.max(0,Math.ceil((S.cs.until-Date.now())/1000));return 'รอ: '+s.msg+' อีก '+Math.floor(l/60)+':'+String(l%60).padStart(2,'0')}
  if(s.k==='event')return 'มีเรื่องด่วนเข้ามา';if(s.k==='escort')return S.cs.esc?'พา'+csPerson(s.who).n+'ไป'+TAGW[s.to]:'ไปรับ'+csPerson(s.who).n+'  '+csLoc(s.who);return 'ส่งบันทึกปิดเคสที่คอมพิวเตอร์'}
function csFloorHint(){const s=csStep();if(!s)return 0;const k=s.k==='escort'&&S.cs.esc?s.to:s.who;if(!k)return 0;if(k.indexOf('@')===0){const m=TAGW[k].match(/ชั้น (\d)/);return m?+m[1]:0}const v=csWhere()[k];return v&&CSLOT[v]?CSLOT[v][0]:0}
function csNote(t){if(!S.cs)return;S.cs.notes.push({t,at:Date.now()})}
function csDone(s){if(!S.cs)return;zgCsComp(s);zgSwpAdd(-3);if(s&&s.note)csNote(s.note);S.cs.i++;S.cs.esc=0;S.cs.tried=[];S.cs.fs=null;const n=csStep();if(n&&n.k==='wait')S.cs.until=Date.now()+n.min*60000*(swRank().fast?.5:1);save();
  if(st.bots)st.bots=st.bots.filter(b=>b.id!=='cs_follow');hud();if(n)setTimeout(()=>{if(S.cs&&st&&st.mode==='play')toast('ขั้นต่อไป: '+csLine())},400)}
function PX(t){t=P(String(t));if(myAvatar().part==='ครับ')return t.replace(/ดิฉัน/g,'ผม').replace(/นะคะ/g,'นะครับ').replace(/ค่ะ/g,'ครับ').replace(/คะ(?=[\s"”'.,!?)]|$)/g,'ครับ');return t.replace(/(ไหม|มั้ย|ไหน|อะไร|ยังไง|อย่างไร|หรือเปล่า|เหรอ|หรือยัง|บ้าง|ใคร|เท่าไร|เท่าไหร่|ไง|มีไหม|ได้ไหม)ครับ/g,'$1คะ').replace(/นะครับ/g,'นะคะ').replace(/ครับ/g,'ค่ะ').replace(/(^|[\s"“(])ผม(?=\s|จะ|ขอ|เข้าใจ|เป็น|ได้|อยาก|ช่วย|ไม่|ก็|รู้|คิด|เห็น|ว่า|เอง|ขอโทษ|ยินดี|ทราบ|ชื่อ|มา|ดู|ฟัง|ถาม|แนะนำ)/g,'$1ดิฉัน')}
function csQA(spk,qs,done){let i=0;const nx=()=>{if(i>=qs.length){done();return}const q=qs[i++];const best=q.o.find(x=>x[1]===2);let opts=shuffle(q.o.slice());
  const show=()=>{const hl=csHintsLeft();const ch=opts.map(o=>({t:PX(o[0]),fn:()=>{st.dlg=null;S.cs.pts+=o[1];S.cs.max+=2;save();
    say('พี่วอลส์','ผู้นิเทศ  ฟีดแบ็ก',supAp(),(o[1]>=2?'ดีมาก! ':o[1]===1?'ใกล้แล้ว ':o[1]===0?'ยังไม่สุด ':'ระวังนะ ')+o[2]+(o[1]<2?'\nคำตอบที่ดีที่สุดคือ '+PX(best[0]):''),nx)}}));if(hl>0&&opts.length>2)ch.push({t:'ขอคำแนะนำหัวหน้างาน (เหลือ '+hl+' ครั้ง)',fn:()=>{S.cs.hu=(S.cs.hu||0)+1;save();const w=opts.filter(o=>o[1]<2).sort((a,b)=>a[1]-b[1])[0];opts=opts.filter(o=>o!==w);st.dlg=null;toast('หัวหน้างานแนะนำ: ตัดตัวเลือกที่ไม่เหมาะสมออก 1 ข้อ');show()}});openDlg({who:spk.n,role:spk.r,ap:spk.ap,text:q.q,choices:ch})};show()};nx()}
function csRun(spk,s,done){const role=spk.r+(s.mood==='angry'?'  กำลังโกรธ':s.mood==='sad'?'  เศร้า':'');const sp={n:spk.n,r:role,ap:spk.ap};
  const fin=()=>{csDone(s);if(done)done()};const after=()=>{if(s.post)say(spk.n,role,spk.ap,s.post,fin);else{st.dlg=null;drawDlg();fin()}};
  const qa=()=>{if(s.q&&s.q.length)csQA(sp,s.q,after);else after()};
  if(s.pre)openDlg({who:spk.n,role,ap:spk.ap,text:s.pre,choices:[{t:'ต่อไป',fn:()=>{st.dlg=null;qa();if(!st.dlg)drawDlg()}}]});else qa()}
function csTalk(b){const s=csStep(),k=b.csWho;const P={n:b.name,r:b.role,ap:b.ap};
  if(s&&s.k==='talk'&&s.who===k){csRun(P,s);return}
  if(s&&s.k==='escort'&&s.who===k&&!S.cs.esc){say(b.name,b.role,b.ap,'"ไปด้วยกันเลยค่ะ เดี๋ยวเดินตามไป"\n\n(พา'+b.name+'ไปที่'+TAGW[s.to]+' แล้วคุยกับเจ้าหน้าที่ตรงนั้น)',()=>{S.cs.esc=1;save();const f={id:'cs_follow',name:b.name,role:b.role,ap:b.ap,spd:200,follow:true,pose:'',dir:'down',ri:0,wait:0,path:[]};st.bots.push(f);botInit0(f);f.x=b.x;f.y=b.y;f.px=b.px;f.py=b.py;hud()});return}
  say(b.name,b.role,b.ap,b.pose==='bed'?'(พักผ่อนอยู่บนเตียง)':'"ขอบคุณที่ช่วยดูแลนะคะ ถ้าต้องการอะไรเพิ่มเรียกได้เลย"')}
function staffTalk(b){const s=csStep(),t=b.tag,P={n:b.name,r:b.role,ap:b.ap};
  if(!S.cs&&t==='@pm'){prMentor(b);return}if(!S.cs&&t==='@hn'){const nx=csQueue().find(x=>!csGate(x));if(nx){openDlg({who:b.name,role:b.role,ap:b.ap,text:'มีเคสรอส่งปรึกษาอยู่ค่ะ: '+nx.t+' ('+nx.type+') จะรับเคสนี้ไหมคะ หรือดูรายการเคสทั้งหมดได้ที่คอมพิวเตอร์',choices:[{t:'รับเคสนี้',fn:()=>{st.dlg=null;drawDlg();csAccept(nx.id)}},{t:'ไว้ก่อน',fn:()=>{st.dlg=null;drawDlg()}}]});return}}
  if(s&&s.k==='talk'&&s.who===t){csRun(P,s);return}
  if(s&&s.k==='escort'&&s.to===t){const f=st.bots.find(x=>x.id==='cs_follow');if(!S.cs.esc){say(b.name,b.role,b.ap,'ต้องพา'+csPerson(s.who).n+'มาด้วยนะคะ ตอนนี้อยู่ที่'+csLoc(s.who));return}
    if(!f||Math.abs(f.x-st.me.x)+Math.abs(f.y-st.me.y)>4){say(b.name,b.role,b.ap,'ญาติยังตามมาไม่ทันค่ะ รอให้เดินมาถึงก่อนนะคะ');return}csRun(P,s);return}
  say(b.name,b.role,b.ap,'"'+b.say[Math.floor(Math.random()*b.say.length)]+'"')}
function csQueue(){const D=S.csDone||{};return CASES.filter(c=>(MAP&&MAP.cmh?!!c.pr:!c.pr)&&!D[c.id]&&!(S.cs&&S.cs.id===c.id)&&(!c.only||csAllOK()))}
function csNeedR(c){const i=SWR.findIndex(r=>r.lvl>=(c.lvl||2));return i<0?SWR.length-1:i}
function csGate(c){if(!c)return 'x';if(c.pr)return prGate(c);if(c.only&&!csAllOK())return 'rank';const t=gTier();if(t<2&&csGranted(c.id))return '';if(t<2)return 'pearl';if((c.lvl||2)>swRank().lvl)return 'rank';return ''}
function csAccept(id){const c=CASES.find(x=>x.id===id);if(!c)return;if(zgSwp().v<20){closeHP();zgSwpLow();return}const g=csGate(c);if(g&&c.pr){toast(prLock(c));return}if(g==='ruby'){toast('สมาชิกฟรีเล่นได้ 1 เคส บัตร RUBY เล่นได้ 5 เคส บัตร PEARL เล่นครบทั้ง '+csN()+' เคส');return}if(g==='pearl'){toast('เคสนี้สำหรับบัตร PEARL  บัตร PEARL เล่นได้ครบทั้ง '+csN()+' เคส');return}if(g==='rank'){toast('เคสระดับ '+(c.lvl||2)+' ต้องเป็น'+swTitle(SWR[csNeedR(c)])+'ก่อน');return}S.cs={id,i:0,pts:0,max:0,notes:[],tried:[],at:Date.now()};save();closeHP();
  if(st.hosp){const m=st.me;(MAP&&MAP.cmh?loadCMH([m.x,m.y],st.cmhF||1):loadHospFree(st.floor,[m.x,m.y]));st.me.dir=m.dir;screen();hud();draw();drawMini()}toast('รับเคส '+c.t+'  '+csLine())}
function csTick(){if(!S.cs)return;const s=csStep();if(!s)return;
  if(s.k==='wait'&&S.cs.until&&Date.now()>=S.cs.until){toast('ครบเวลารอแล้ว');csDone(s);return}
  if(s.k==='event'&&st.hosp&&!st.dlg&&st.mode==='play'){openDlg({who:s.by||'แจ้งข่าว',role:s.role||'เรื่องด่วน',ap:NPCA.nurse,text:s.text,choices:[{t:'รับทราบ',fn:()=>{st.dlg=null;drawDlg();csDone(s)}}]})}}
function zgSwpChip(){zgTickStart();const v=zgSwp().v;return `<button class="zsw-c ${v<20?'lo':v<40?'md':''}" data-h="swp" aria-label="พลังใจ ${v} จาก 100"><span>พลังใจ</span><i><u style="width:${v}%"></u></i><b>${v}</b></button>`}
