function zgHvLbl(k){if(k==='hv:back')return 'ขึ้นรถ สรุปการเยี่ยมบ้าน';const H=st.hv&&ZG_HV[st.hv];const o=H&&H.obs[k.slice(3)];return o?'สังเกต: '+o[0]:''}
function zgHvLine(){const c=S.zhvCur;if(!c)return '';const H=ZG_HV[c.id];const no=Object.keys(c.obs).length,nt=Object.keys(c.talk).length;return 'สังเกต '+no+'/4 จุด  คุยแล้ว '+nt+'/2 คน'+(no>=3&&nt>=2?'  กลับไปที่รถเพื่อสรุป':'')}
function zgHvMenu(){if(!zxOK()){toast('ออกเยี่ยมบ้าน เฉพาะบัตร PEARL');return}const D=S.zhv||{};openHP('ออกเยี่ยมบ้าน',`<div class="zhv-m"><p class="zhv-i">เลือกบ้านที่จะไปเยี่ยม แต่ละชุมชนมีปัญหาและแหล่งช่วยเหลือต่างกัน ไปสังเกตสภาพบ้านอย่างน้อย 3 จุด คุยกับครอบครัวและคนในชุมชน แล้วกลับมาสรุปที่รถ</p>${ZG_HV_ORDER.map(id=>{const H=ZG_HV[id],r=D[id];return `<div class="zhv-c zhv-${id}"><div class="zhv-ct"><span class="zhv-tg">${H.tag}</span>${r?`<span class="zhv-g">ผล: ${r.g}</span>`:''}</div><b>${H.n}</b><small>${H.pt}</small><p>${H.brief}</p><button class="g-btn ${r?'':'big'}" data-h="hvgo" data-v="${id}">${r?'ไปเยี่ยมอีกครั้ง':'ออกเยี่ยมบ้าน'}</button></div>`}).join('')}</div>`,'camp')}
function zgHvGo(id){if(!zxOK()){toast('ออกเยี่ยมบ้าน เฉพาะบัตร PEARL');return}const H=ZG_HV[id];if(!H)return;closeHP();S.zhvCur={id,obs:{},talk:{},at:Date.now()};save();
  loadPlace('hv:'+id,{mk:id==='condo'?'home':'village',place:H.n});st.hv=id;const B=ZG_HV_BOT[id];
  [['fam',H.fam],['com',H.com]].forEach(([k,P])=>{const b={id:'hv_'+k,name:P.name,role:P.role,ap:AP(NPCA[P.ap]||NPCA.nid),spd:220,pose:'',dir:'down',ri:0,wait:0,path:[],route:[[B[k][0],B[k][1],9e9,'','down','']],say:['...'],hv:k};botInit0(b);st.bots.push(b)});
  screen();hud();draw();drawMini();
  say('หัวหน้างาน','ก่อนลงรถ',NPCA.sup,'ถึง'+H.n+' ('+H.t+') แล้ว\n\n'+H.brief+'\n\nสิ่งที่ต้องทำ\nเดินสังเกตสภาพบ้านอย่างน้อย 3 จุด\nคุยกับ'+H.fam.name+' ('+H.fam.role+')\nคุยกับ'+H.com.name+' ('+H.com.role+')\nกลับมาที่รถเพื่อสรุปการเยี่ยมบ้าน')}
function zgHvAct(k){const c=S.zhvCur;if(!st.hv||!c)return false;const H=ZG_HV[st.hv];
  if(k==='hv:back'){const no=Object.keys(c.obs).length,nt=Object.keys(c.talk).length;
    if(no>=3&&nt>=2){zgHvForm();return true}
    openDlg({who:'คนขับรถ',role:'รถพยาบาลของโรงพยาบาล',ap:NPCA.boon,text:'ยังเก็บข้อมูลไม่ครบนะ\nสังเกตแล้ว '+no+'/3 จุดขั้นต่ำ  คุยแล้ว '+nt+'/2 คน'+(c.talk.fam==null?'\nยังไม่ได้คุยกับ'+H.fam.name:'')+(c.talk.com==null?'\nยังไม่ได้คุยกับ'+H.com.name:''),choices:[{t:'เก็บข้อมูลต่อ',fn:()=>{st.dlg=null;drawDlg()}},{t:'กลับโรงพยาบาลเลย (ไม่สรุปผล)',fn:()=>{st.dlg=null;drawDlg();zgHvBack()}}]});return true}
  const o=H.obs[k.slice(3)];if(!o)return false;const first=!c.obs[k];c.obs[k]=1;save();hud();say(myAvatar().name,'สังเกต  '+o[0],myAvatar(),o[1]+(first?'\n\n(บันทึกข้อสังเกตแล้ว '+Object.keys(c.obs).length+'/4)':''));return true}
function zgHvTalk(b){const c=S.zhvCur;if(!c||!st.hv)return;const H=ZG_HV[st.hv],P=H[b.hv];
  if(c.talk[b.hv]!=null){say(P.name,P.role,b.ap,P.info);return}
  openDlg({who:P.name,role:P.role,ap:b.ap,text:P.q,choices:shuffle(P.o.slice()).map(o=>({t:o[0],fn:()=>{st.dlg=null;c.talk[b.hv]=o[1];save();hud();
    say(myAvatar().name,(o[1]===2?'ดีมาก':o[1]===1?'พอใช้':'ลองคิดใหม่')+'  การสื่อสาร',myAvatar(),o[2]+(o[1]<2?'\n\nแนวทางที่ดีที่สุด: '+P.o.find(x=>x[1]===2)[0]:''),()=>say(P.name,P.role,b.ap,P.info))}}))})}
function zgHvForm(){const H=ZG_HV[st.hv];const pick=(cls,one)=>`const g=this.closest('.${cls}');${one?`g.querySelectorAll('.zhv-o').forEach(e=>e.classList.remove('on'));this.classList.add('on')`:`this.classList.toggle('on')`}`;
  const shuf=a=>a.map((x,i)=>[x,i]).sort((p,q)=>((p[1]*7+3)%5)-((q[1]*7+3)%5));
  openHP('สรุปการเยี่ยมบ้าน  '+H.n,`<div class="zhv-f"><p class="zhv-i">ใช้ข้อมูลที่สังเกตและคุยมา ตอบ 3 ข้อด้านล่าง</p>
   <h4>1. ความต้องการของครอบครัวนี้คืออะไรบ้าง <small>เลือกได้หลายข้อ</small></h4><div class="zhv-g1">${shuf(H.needs).map(([x,i])=>`<button type="button" class="zhv-o" data-i="${i}" onclick="${pick('zhv-g1',0)}"><i></i>${x[0]}</button>`).join('')}</div>
   <h4>2. แผนการช่วยเหลือที่เหมาะที่สุด</h4><div class="zhv-g2">${shuf(H.plan).map(([x,i])=>`<button type="button" class="zhv-o r" data-i="${i}" onclick="${pick('zhv-g2',1)}"><i></i>${x[0]}</button>`).join('')}</div>
   <h4>3. หน่วยงานหลักที่ต้องส่งต่อ</h4><div class="zhv-g3">${shuf(H.ref).map(([x,i])=>`<button type="button" class="zhv-o r" data-i="${i}" onclick="${pick('zhv-g3',1)}"><i></i>${x[0]}</button>`).join('')}</div>
   <div class="hp-row"><button class="g-btn big" data-h="hvsub">ส่งสรุปให้หัวหน้า</button></div></div>`,'camp')}
function zgHvSubmit(){const el=root.querySelector('.g-hp');if(!el||!st.hv)return;const H=ZG_HV[st.hv],c=S.zhvCur,id=st.hv;
  const sel=g=>[...el.querySelectorAll('.'+g+' .zhv-o.on')].map(e=>+e.dataset.i);const ns=sel('zhv-g1'),pl=sel('zhv-g2')[0],rf=sel('zhv-g3')[0];
  if(!ns.length||pl==null||rf==null){toast('ตอบให้ครบทั้ง 3 ข้อก่อนนะ');return}
  let np=0;ns.forEach(i=>np+=H.needs[i][1]?1:-1);np=Math.max(0,np);const nm=H.needs.filter(x=>x[1]).length;
  const pp=H.plan[pl][1],rp=H.ref[rf][1],tf=c.talk.fam||0,tc=c.talk.com||0,ob=Object.keys(c.obs).length;
  const P=np+pp+rp+tf+tc+(ob>=4?1:0),M=nm+2+2+2+2+1,g=csGrade(P,M);
  zcAdd('assess',np+(ob>=4?1:0),nm+1);zcAdd('coord',pp+rp,4);zcAdd('comm',tf+tc,4);
  const coin=earn(Math.round(5+10*P/M),'hcase','hv:'+id+':'+isoD(new Date()))||0;S.zhv=S.zhv||{};const old=S.zhv[id];if(!old||P/M>=old.p/old.m)S.zhv[id]={g,p:P,m:M,at:Date.now()};S.zhvCur=null;save();
  const miss=H.needs.filter((x,i)=>x[1]&&ns.indexOf(i)<0).map(x=>x[0]),wrong=ns.filter(i=>!H.needs[i][1]).map(i=>H.needs[i][0]);
  zgHvBack(1);
  openHP('ผลการเยี่ยมบ้าน  '+H.n,`<div class="pc"><div class="pc-sum"><b>${g}</b><span>คะแนน ${P}/${M}${coin?'  รับ '+coin+' เหรียญ':''}</span></div><div class="zhv-r">
   <h4>ความต้องการของครอบครัว</h4><p>${miss.length?'ยังขาด: '+miss.join('  '):'ครบทุกข้อ'}${wrong.length?'<br>ไม่ควรเลือก: '+wrong.join('  '):''}</p>
   <h4>แผนการช่วยเหลือ</h4><p>${pp===2?'เลือกได้ดีที่สุด':'แผนที่ดีที่สุด: '+H.plan.find(x=>x[1]===2)[0]}</p>
   <h4>หน่วยงานที่ส่งต่อ</h4><p>${H.ref[rf][1]===2?'ถูกต้อง  ':'ควรส่งต่อ: '+H.ref.find(x=>x[1]===2)[0]+'  '}${H.ref.find(x=>x[1]===2)[2]}</p>
   <h4>การสื่อสาร</h4><p>คุยกับ${H.fam.name} ${['ต้องปรับ','พอใช้','ดีมาก'][tf]}  คุยกับ${H.com.name} ${['ต้องปรับ','พอใช้','ดีมาก'][tc]}</p></div></div>`,'camp pc')}
function zgHvBack(silent){st.hv=null;if(!silent){S.zhvCur=null;save()}loadHospFree(1);screen();hud();draw();drawMini();if(!silent)toast('กลับถึงโรงพยาบาลแล้ว')}
