const ZX_JAS='บัตรหน้าที่ (Job Action Sheet)\nตำแหน่ง: หัวหน้าหน่วยช่วยเหลือผู้ป่วยและครอบครัว (Patient Family Assistance Branch)\nรายงานต่อ: หัวหน้าฝ่ายปฏิบัติการ ศูนย์สั่งการโรงพยาบาล\nหน่วยในความรับผิดชอบ: ศูนย์ข้อมูลครอบครัว ศูนย์ติดตามผู้ป่วย มุมเด็กพลัดหลง ห้องแจ้งข่าว จุดปฐมพยาบาลทางใจ\nชั่วโมงแรก: รายงานตัว รับข้อมูลสถานการณ์ มอบหมายลูกทีม ตั้งศูนย์ ประสานประชาสัมพันธ์ รายงานสถานการณ์ตามรอบ\nข้อห้าม: ไม่ให้ข้อมูลผู้ป่วยกับสื่อ ไม่แจ้งการเสียชีวิตทางโทรศัพท์ ไม่ส่งตัวเด็กโดยไม่ยืนยันผู้รับ ไม่ยืนยันตัวผู้ป่วยจากใบหน้าอย่างเดียว';
function zxE(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function zxMM(s){s=Math.max(0,Math.floor(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function zxTD(id){return ZX_T.find(x=>x.id===id)}
function zxSc(){const C=S.zdrCur;return C?ZX_SC[C.sc]:null}
function zxRoom(td){return td.room==='*'?(zxSc().tasks.special.room):td.room}

