function zxScene(){const C=S.zdrCur;if(!C||!st.hosp||st.floor!==1)return;const av=ZX_T.filter(x=>zxAvail(x.id)).map(x=>x.id).join(',');const sig=C.ph+'|'+av;const has=st.bots.some(b=>b.zd);if(has&&st.zxSig===sig)return;st.zxSig=sig;
 const want=zxCast(),ids=new Set(want.map(w=>w.id));st.bots=st.bots.filter(b=>!b.zd||ids.has(b.id));const cur=new Set(st.bots.filter(b=>b.zd).map(b=>b.id));
 want.forEach(w=>{if(cur.has(w.id))return;const R=ZX_R[w.area];const p=w.fix||randTile(R);const b={id:w.id,name:w.name,role:w.role,ap:w.ap,spd:w.spd||260,pose:w.pose||'',dir:'down',ri:0,wait:0,path:[],say:w.say&&w.say[0]?w.say:[(ZX_BK[w.pool]||ZX_BK.fam)[0]],zd:1,zp:w.pool,zxT:w.zxT||null};
  if(w.fix||w.still)b.route=[[p[0],p[1],9e9,w.pose||'',w.still?'down':'down','']];else b.wander=R;botInit0(b);if(!w.fix&&!w.still){b.x=p[0];b.y=p[1];b.px=b.x*T;b.py=b.y*T}st.bots.push(b)})}
function zxBarkTick(){const C=S.zdrCur;if(!C||!st.hosp||st.floor!==1)return;const now=performance.now(),me=st.me;const Z=st.bots.filter(b=>b.zd&&!b.hidden&&Math.abs(b.x-me.x)<=11&&Math.abs(b.y-me.y)<=9);
 const act=Z.filter(b=>b.bkT>now).length;let n=Math.min(3,(C.ph===2?6:3)-act);while(n-->0&&Z.length){if(Math.random()>.8)break;const b=Z[Math.floor(Math.random()*Z.length)];if(b.bkT>now)continue;
  const pool=b.zp==='inj'?ZX_INJ[C.sc]||ZX_INJ.bus:ZX_BK[b.zp]||ZX_BK.fam;b.bk=pool[Math.floor(Math.random()*pool.length)];b.bkT=now+2400+Math.random()*1200}}
function zxBark(c,b){const now=performance.now();if(b.zxT){const y=b.py-16+Math.round(Math.sin(now/220)*1.5);c.fillStyle='#E31414';c.beginPath();c.arc(b.px+16,y,6,0,Math.PI*2);c.fill();c.fillStyle='#FFFFFF';c.fillRect(b.px+15,y-4,2,5);c.fillRect(b.px+15,y+2,2,2)}
 if(!(b.bkT>now)||!b.bk)return;c.save();c.font='bold 8px "Chulalongkorn","IBM Plex Sans Thai",sans-serif';const w=Math.ceil(c.measureText(b.bk).width)+10,h=13,x=Math.round(b.px+16-w/2),y=Math.round(b.py-(b.zxT?36:22));
 c.fillStyle='rgba(255,255,255,.96)';c.strokeStyle=b.zp==='staff'||b.zp==='cmd'?'#E31414':'#E8A598';c.lineWidth=1;c.beginPath();if(c.roundRect)c.roundRect(x+.5,y+.5,w,h,5);else c.rect(x+.5,y+.5,w,h);c.fill();c.stroke();
 c.beginPath();c.moveTo(b.px+13,y+h);c.lineTo(b.px+16,y+h+4);c.lineTo(b.px+19,y+h);c.closePath();c.fillStyle='rgba(255,255,255,.96)';c.fill();
 c.fillStyle=b.zp==='staff'||b.zp==='cmd'?'#B5141C':'#2B1A1F';c.textAlign='center';c.textBaseline='middle';c.fillText(b.bk,x+w/2+.5,y+h/2+1);c.restore()}

