const ZT_NO=[['ถามขอบเขตงานและเกณฑ์รับส่งต่อของหน่วยงาน แล้วตกลงช่องทางประสานและผู้ประสานงานหลักของทั้งสองฝ่าย',2,'เครือข่ายที่ใช้งานได้จริงต้องรู้เกณฑ์ของกันและกัน และมีช่องทางประสานที่ชัด การส่งต่อจึงไม่ผิดที่และไม่ล่าช้า'],['แลกไลน์ส่วนตัวไว้ ถ้ามีเคสจะทักไปขอความช่วยเหลือเป็นการส่วนตัว',1,'ติดต่อง่ายขึ้น แต่ถ้าพึ่งความสัมพันธ์ส่วนตัวอย่างเดียว เมื่อมีคนย้ายงานเครือข่ายก็หายไป ควรมีช่องทางของหน่วยงานด้วย'],['ขอให้หน่วยงานรับทุกเคสที่โรงพยาบาลส่งไปโดยไม่ต้องคัดกรองซ้ำ',0,'แต่ละหน่วยงานมีภารกิจและข้อจำกัดของตัวเอง การขอให้รับทุกเคสโดยไม่ดูเกณฑ์ทำให้ความร่วมมือไม่ยั่งยืน']];
const ZT_OC=[
 {id:'child',c:'assess',t:'เด็กชายอายุ 4 ขวบมาห้องฉุกเฉินด้วยแขนหัก แม่เล่าว่าตกเตียง แต่แพทย์พบรอยช้ำหลายระยะตามหลังและต้นขา แม่ต้องการพากลับบ้านคืนนี้',
  o:[['ขอให้แพทย์รับเด็กไว้ในโรงพยาบาลคืนนี้เพื่อความปลอดภัย ให้บันทึกบาดแผลอย่างละเอียด แล้วเข้าประเมินครอบครัวร่วมกับทีม OSCC แต่เช้า',2,'ความปลอดภัยของเด็กมาก่อน การรับไว้รักษาทำให้เด็กปลอดภัยโดยไม่ต้องเผชิญหน้ากล่าวหาแม่กลางดึก และทีมสหวิชาชีพประเมินได้ครบถ้วน'],['ให้พยาบาลแจ้งตำรวจมาที่ห้องฉุกเฉินเดี๋ยวนี้ และบอกแม่ว่าสงสัยเรื่องการทำร้ายเด็ก',1,'การแจ้งเป็นหน้าที่ตามกฎหมาย แต่การบอกแม่ทันทีกลางดึกเสี่ยงให้แม่พาเด็กออกไป ควรให้เด็กปลอดภัยในโรงพยาบาลก่อน'],['ให้แม่พาเด็กกลับบ้านได้ พรุ่งนี้จะโทรนัดมาคุยที่กลุ่มงาน',0,'ปล่อยเด็กกลับไปในสภาพแวดล้อมที่อาจไม่ปลอดภัย ทั้งที่มีสัญญาณการถูกทำร้ายชัดเจน']]},
 {id:'dv',c:'coord',t:'หญิงอายุ 32 ปีถูกสามีทำร้าย แผลที่ศีรษะเย็บเรียบร้อยแล้ว เธอไม่กล้ากลับบ้านเพราะสามีขู่ซ้ำ และไม่มีญาติอยู่ในจังหวัด',
  o:[['ขอคุยกับผู้ป่วยทางโทรศัพท์ ประเมินความเสี่ยงซ้ำ แล้วประสานศูนย์ช่วยเหลือสังคม 1300 หาที่พักฉุกเฉินคืนนี้ หรือขอรับไว้สังเกตอาการก่อน',2,'ความปลอดภัยคืนนี้คือเป้าหมายแรก ศูนย์ช่วยเหลือสังคม 1300 ประสานที่พักฉุกเฉินได้ตลอด 24 ชั่วโมง'],['ให้ผู้ป่วยนั่งรอที่ห้องฉุกเฉินจนเช้า แล้วค่อยมาพบนักสังคมสงเคราะห์',1,'ปลอดภัยในระยะสั้น แต่ห้องฉุกเฉินไม่ใช่ที่พัก และผู้ป่วยยังไม่มีแผนความปลอดภัย'],['แนะนำให้กลับบ้านไปคุยกับสามีดีๆ ก่อน',0,'ส่งผู้ป่วยกลับไปหาผู้กระทำที่ขู่ซ้ำ เสี่ยงต่อการถูกทำร้ายรุนแรงขึ้น']]},
 {id:'death',c:'comm',t:'ผู้ป่วยชายอายุ 45 ปีเสียชีวิตจากอุบัติเหตุ ภรรยากับลูกวัยรุ่นสองคนกำลังเดินทางมา แพทย์ขอให้ช่วยดูแลครอบครัว',
  o:[['เดินทางเข้าโรงพยาบาล เตรียมห้องที่เป็นส่วนตัว อยู่ด้วยขณะแพทย์แจ้งข่าว และดูแลความเศร้าของครอบครัวก่อนเรื่องเอกสาร',2,'การแจ้งข่าวร้ายควรทำในที่ส่วนตัว มีคนดูแลความรู้สึกอยู่ด้วย ส่วนเรื่องเอกสารรอได้'],['ให้พยาบาลแจ้งข่าวเอง แล้วนัดครอบครัวมาคุยเรื่องเอกสารรับศพพรุ่งนี้เช้า',1,'ไม่ผิดขั้นตอน แต่ครอบครัวต้องผ่านช่วงที่หนักที่สุดโดยไม่มีคนดูแลจิตใจ'],['ให้พยาบาลแจ้งข่าวทางโทรศัพท์ก่อนครอบครัวมาถึง จะได้ไม่ต้องรอนาน',0,'การแจ้งข่าวการเสียชีวิตขณะญาติกำลังเดินทางเสี่ยงต่ออุบัติเหตุ และไม่มีใครอยู่ดูแลความรู้สึก']]},
 {id:'elder',c:'coord',t:'ชายอายุ 81 ปี มีภาวะสมองเสื่อม มีคนพบเดินหลงอยู่ที่ตลาดตอนสามทุ่ม ไม่มีบัตรประชาชน จำบ้านไม่ได้ แพทย์ตรวจแล้วไม่มีปัญหาเร่งด่วนทางร่างกาย',
  o:[['ขอให้รับไว้สังเกตอาการคืนนี้ แจ้งสถานีตำรวจท้องที่เพื่อตรวจรายงานคนหาย แล้วพรุ่งนี้เช้าประสานผู้ใหญ่บ้านหรือ อบต. ช่วยตามหาครอบครัว',2,'ผู้สูงอายุสมองเสื่อมไม่ควรถูกปล่อยออกไปตอนกลางคืน ตำรวจมีข้อมูลการแจ้งคนหาย ช่วยให้เจอครอบครัวได้เร็วที่สุด'],['ส่งต่อไปสถานคุ้มครองคนไร้ที่พึ่งคืนนี้เลย',1,'เป็นทางเลือกเมื่อหาครอบครัวไม่พบ แต่ควรตามหาครอบครัวก่อน และการย้ายกลางดึกทำให้ผู้ป่วยสมองเสื่อมสับสนมากขึ้น'],['ให้ รปภ. พาไปส่งที่ตลาดที่พบตัว เผื่อญาติจะมาตามหา',0,'ปล่อยผู้สูงอายุที่ช่วยเหลือตัวเองไม่ได้ไว้ในที่สาธารณะตอนกลางคืน เสี่ยงต่ออุบัติเหตุและอันตราย']]},
 {id:'mig',c:'ethic',t:'แรงงานชาวเมียนมาอายุ 24 ปี นิ้วขาดจากเครื่องจักรในโรงงาน นายจ้างพามาส่งแล้วกลับไป ผู้ป่วยพูดไทยได้น้อยและกังวลเรื่องค่ารักษามาก',
  o:[['ขอให้พยาบาลหาล่ามหรือเจ้าหน้าที่ที่พูดภาษาเมียนมาช่วยสื่อสาร ยืนยันว่าการรักษาจะดำเนินไปก่อน แล้วพรุ่งนี้ประสานสำนักงานประกันสังคมเรื่องกองทุนเงินทดแทน',2,'การบาดเจ็บจากการทำงานเข้าข่ายสิทธิกองทุนเงินทดแทน และการสื่อสารด้วยภาษาที่ผู้ป่วยเข้าใจเป็นพื้นฐานของการยินยอมรับการรักษา'],['โทรหานายจ้างให้กลับมารับผิดชอบค่ารักษาเดี๋ยวนี้',1,'นายจ้างมีส่วนรับผิดชอบจริง แต่ผู้ป่วยยังไม่เข้าใจสิ่งที่เกิดขึ้น และยังไม่ได้ตรวจสอบสิทธิที่เขาควรได้'],['บอกผู้ป่วยว่าต้องรอให้นายจ้างมาก่อนจึงจะผ่าตัดได้',0,'การรักษาฉุกเฉินต้องมาก่อนเรื่องค่าใช้จ่าย การให้ผู้ป่วยรอเพราะเงินอาจทำให้เสียนิ้วถาวร']]}];
function ztSvToday(){const d=isoD(new Date());if(S.svD===d&&S.svLast){const x=ZT_SV.find(v=>v.id===S.svLast);if(x)return x}const done=S.svDone||{};const pend=ZT_SV.filter(x=>!done[x.id]);const pool=pend.length?pend:ZT_SV;return pool[ztDoy()%pool.length]}
function ztNetToday(){const d=isoD(new Date());if(S.netD===d&&S.netLast){const x=ZT_NET.find(v=>v.id===S.netLast);if(x)return x}const N=S.net||{};const pend=ZT_NET.filter(x=>!N[x.id]);const pool=pend.length?pend:ZT_NET;return pool[ztDoy()%pool.length]}
function ztLeave(b){const E=MAP.exit||MAP.start;b.leaving=true;b.say=null;b.pose='';b.wait=0;b.bub='';b.arrived=null;const p=bfsB(b.x,b.y,E[0],E[1]);if(!p){b.off=true;b.hidden=true;return}b.path=p;b.arrive={x:E[0],y:E[1],dw:0,pose:'off'};if(!p.length){b.arrive=null;b.arrived={pose:'off'}}}
function ztByeTick(){if(!st||!st.house||st.dlg||!st.bots)return;st.bots.forEach(b=>{if(b.bye&&!b.leaving&&!b.off){b.bye=0;ztLeave(b)}})}
function ztBye(id){const b=st.bots&&st.bots.find(x=>x.id===id);if(b)b.bye=1}
function ztBots(B){const td=isoD(new Date());const sv=ztSvToday(),I=ZT_IN[sv.i];if(S.svD!==td)B({id:'zt_sv',zt:'sv',name:I[0],role:'นักศึกษาฝึกงาน  รอปรึกษา',ap:AP(I[1]),spd:300,pose:'sit',dir:'right',route:[[17,5,999999,'sit','right','']],say:['มีเคสอยากปรึกษาค่ะ']});
 const g=ztNetToday();if(S.netD!==td)B({id:'zt_g',zt:'g',name:g.n,role:g.r+'  แขกที่มาเยี่ยม',ap:AP(g.ap),spd:300,pose:'sit',dir:'left',route:[[19,13,999999,'sit','left','']],say:['แวะมาเยี่ยม']})}
function ztNetHit(nm){const N=S.net||{};const g=ZT_NET.find(x=>N[x.id]&&x.kw.some(k=>String(nm).indexOf(k)>=0));return g?g.n+' '+g.r:''}
