/* ---------- input ---------- */
const KEYMAP={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
function onKey(e){if(!mounted||V.view!=='game')return;if(e.target.matches&&e.target.matches('input,textarea'))return;const d=KEYMAP[e.code];
  if(st.dlg&&e.type==='keydown'){const n=parseInt(e.key,10);const btns=root.querySelectorAll('.g-ch .g-btn');if(n>=1&&n<=btns.length){e.preventDefault();btns[n-1].click()}else if((e.code==='Space'||e.code==='Enter')&&btns.length===1){e.preventDefault();btns[0].click()}return}
  if(st.mode!=='play')return;
  if(d){e.preventDefault();keys[d]=e.type==='keydown';if(e.type==='keydown')st.me.path=[]}
  else if(e.type==='keydown'&&(e.code==='Space'||e.code==='Enter'||e.code==='KeyE')){e.preventDefault();interact(near())}}
