return {_dlg:d=>openDlg(d),_maxSW:(full)=>{S.csDone=S.csDone||{};let ch=0;CASES.forEach(c=>{const d=S.csDone[c.id];if(!d||d.g!=='ดีเยี่ยม'){const m=2*c.steps.reduce((a,s)=>a+((s.q||[]).length)+(s.k==='form'?s.f.length:0)+(s.k==='phone'?1:0),0);S.csDone[c.id]={pts:m,max:m,g:'ดีเยี่ยม',at:Date.now(),notes:(c.steps.filter(s=>s.note).map(s=>({t:s.note,at:Date.now()})))};ch=1}});if(full){S.campSeen=S.campSeen||{};Object.keys(FACS).forEach(k=>{if(!S.campSeen[k]){S.campSeen[k]=1;ch=1}});if((S.nightBest||0)<10){S.nightBest=10;ch=1}}return ch},swInfo:()=>{const x=swXP(),ri=swRankI(x),R=SWR[ri],N=SWR[ri+1],D=S.csDone||{};const L=CASES.filter(c=>D[c.id]);return {title:swTitle(R),n:R.n,ri,max:SWR.length-1,xp:x,next:N?swTitle(N):'',need:N?N.xp-x:0,pct:N?Math.round((x-R.xp)/(N.xp-R.xp)*100):100,closed:L.length,total:csN(),hard:L.filter(c=>c.lvl===4).length,top:L.filter(c=>D[c.id].g==='ดีเยี่ยม').length,perks:R.p,nextPerks:N?N.p:[],active:S.cs?(CASES.find(c=>c.id===S.cs.id)||{}).t:''}},mount,unmount,screenOf,_day:()=>DAY,_night:()=>{loadNight();st.mode='play';screen();hud();draw()},_st:()=>st,_P:P,_cs:()=>({loadCMH,prGo,zxTask,zxRun,zxAvail,ZX_T,zxStat,zxRoom,zdInfo,zxAAR,zdChip,zqNext,zqTalk,zqDesk,zdStart,zdRun,zdSubmit,zdEnd,zdTick,ZD_ST,zsStart,zsTasks,zsGet,zsNow,zgTick,zgHvGo,zgHvAct,zgHvSubmit,zgHvForm,zgHvTalk,zgFile,zbCheck,zcAdd,zgHev,zgSwp,zgSwpAdd,zgSwpRest,zgPb,zgSwpPanel,ZG_EV,AGENCY,CS,csStep,csWhere,csTalk,staffTalk,csPhone,csDone,csClose,csAccept,csTick,pcPanel,nbPanel,CSLOT,TAGW,CASES,loadHospFree,dutyTick,SWR,swXP,swRankI}),_audit:()=>{const seen=new Set([K(st.me.x,st.me.y)]),q=[[st.me.x,st.me.y]];while(q.length){const [x,y]=q.pop();[[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{const nx=x+dx,ny=y+dy,k=K(nx,ny);if(nx<0||ny<0||nx>=MAP.w||ny>=MAP.h||seen.has(k)||BLOCK.has(k))return;seen.add(k);q.push([nx,ny])})}const adj=(x,y)=>seen.has(K(x,y))||[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>seen.has(K(x+dx,y+dy)));const bad=[];st.objs.forEach(o=>{if(!o.act||o.walk)return;let ok=false;for(let dy=0;dy<o.h;dy++)for(let dx=0;dx<o.w;dx++)if(adj(o.x+dx,o.y+dy))ok=true;if(!ok)bad.push('obj '+o.t+' '+o.x+','+o.y)});st.bots.forEach(b=>{(b.route||[]).forEach(r=>{if(!adj(r[0],r[1]))bad.push('bot '+b.id+' '+r[0]+','+r[1])})});(MAP.home||[]).forEach(h=>{if(!seen.has(K(h[0],h[1])))bad.push('home '+h)});const occ={};st.bots.forEach(b=>{if(b.route&&b.route.length===1){const k=b.route[0][0]+','+b.route[0][1];(occ[k]=occ[k]||[]).push(b.id)}});return {bad,vis:st.bots.filter(b=>!b.hidden).length,tot:st.bots.length,dup:Object.entries(occ).filter(([k,v])=>v.length>1&&st.bots.filter(b=>v.includes(b.id)&&b.duty).length<2).map(([k,v])=>k+':'+v.join('/'))}},_reach:()=>{const seen=new Set([K(st.me.x,st.me.y)]),q=[[st.me.x,st.me.y]];while(q.length){const [x,y]=q.pop();[[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{const nx=x+dx,ny=y+dy,k=K(nx,ny);if(nx<0||ny<0||nx>=MAP.w||ny>=MAP.h||seen.has(k)||BLOCK.has(k))return;seen.add(k);q.push([nx,ny])})}return (MAP.rooms||[]).map(r=>{const n=Array.isArray(r)?r:[r.n,...(r.a||[])];let c=0;for(let y=n[2];y<=n[4];y++)for(let x=n[1];x<=n[3];x++)if(seen.has(K(x,y)))c++;return n[0]+':'+c})},_tv:()=>!!(st&&st.tv),_house:()=>{loadHouse();st.mode='play';screen();hud();draw()},_act:(x,y)=>{const tl=targets().filter(t=>t.x===x&&t.y===y);const t=tl.find(t=>t.bot&&t.bot.friend)||tl.find(t=>!t.bot)||tl[0];if(t){const p=bfs(st.me.x,st.me.y,(a,b)=>Math.abs(a-x)+Math.abs(b-y)===1);if(p&&p.length){const l=p[p.length-1];st.me.x=l[0];st.me.y=l[1];st.me.px=l[0]*T;st.me.py=l[1]*T}interact(t);return true}return false},_run:id=>{const t=DAY.tasks.find(t=>t.id===id);runTask(t,speaker(t.at))},
  _warp:(key)=>{const tg=targets().find(t=>t.key===key);if(!tg)return false;const p=bfs(st.me.x,st.me.y,(a,b)=>Math.abs(a-tg.x)+Math.abs(b-tg.y)===1);if(!p)return 'nopath';const l=p.length?p[p.length-1]:[st.me.x,st.me.y];st.me.x=l[0];st.me.y=l[1];st.me.px=l[0]*T;st.me.py=l[1]*T;faceTo(tg);interact(tg);return true}};
